async function api(path,opt={}){const h=new Headers(opt.headers||{});if(!h.has('Content-Type')&&opt.body)h.set('Content-Type','application/json');const t=token();if(t&&!h.has('Authorization'))h.set('Authorization','Bearer '+t);const r=await fetch(API+path,{credentials:'include',...opt,headers:h});const d=await r.json().catch(()=>({success:false,message:'Invalid server response'}));if(!r.ok||d.success===false)throw Object.assign(new Error(d.message||`Request failed (${r.status})`),{status:r.status});return d}
function toast(message,type='info'){const n=window.vexaReactNotify;if(n){const f=n[type==='success'?'showSuccess':type==='error'?'showError':type==='warning'?'showWarning':'showInfo'];if(f){f(message);return}}let e=$('.vx-toast-stack');if(!e){e=document.createElement('div');e.className='vx-toast-stack';document.body.appendChild(e)}const x=document.createElement('div');x.className='vx-toast '+type;x.textContent=message;e.appendChild(x);setTimeout(()=>x.remove(),3600)}
const pages={home:['⌂','Home'],personal:['👤','Personal info'],security:['🛡','Security'],privacy:['◉','Privacy & data'],password:['🔑','Password'],devices:['📱','Your devices'],sessions:['◷','Active sessions'],apps:['▦','Connected apps'],notifications:['🔔','Notifications'],people:['👥','People & sharing'],verification:['✓','Verification'],activity:['↗','Account activity'],recovery:['♻','Account recovery'],support:['?','Help & support'],delete:['⚠','Delete account']};
